out.iframes=[...document.querySelectorAll('iframe')].map(f=>({src:f.src,title:f.title,style:f.getAttribute('style'),w:f.offsetWidth,h:f.offsetHeight,ah:f.getAttribute('aria-hidden'),ti:f.tabIndex}));
