{"function":"() => {
const strip=(root)=>{const c=root.cloneNode? null:null; let h=root.innerHTML; return h.replace(/<style>[\s\S]*?<\/style>/g,'').replace(/<!--.*?-->/g,'').replace(/\s(_ngcontent|_nghost)[^=\s]*(="[^"]*")?/g,'').replace(/\s+/g,' ');};
const t=document.querySelector('br-tab');
return {tab:strip(t.shadowRoot).slice(0,2500), item:strip(document.querySelector('br-tab-item').shadowRoot).slice(0,800), hdr:strip(document.querySelector('br-header').shadowRoot).slice(0,3000), bc:strip(document.querySelector('br-breadcrumb').shadowRoot).slice(0,1500)};}"}

{"function":"() => {
const clean=h=>h.replace(/<style>[\s\S]*?<\/style>/g,'').replace(/<!--.*?-->/g,'').replace(/\s(_ngcontent|_nghost)[^=\s]*(="[^"]*")?/g,'').replace(/\s+/g,' ');
const r=document.querySelector('pnip-header');
const m=document.querySelector('pnip-mpa-processos');
let h=clean(m.outerHTML);
// cut table body rows after first 2
return {hdr:clean(r.outerHTML).slice(0,3000), len:h.length, top:h.slice(0,6000)};}"}

{"function":"() => {
const parse=c=>{const m=c.match(/[\d.]+/g).map(Number);return m;};
const lum=([r,g,b])=>{const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)};
const bgOf=el=>{while(el){const c=getComputedStyle(el).backgroundColor; const p=parse(c); if(p.length<4||p[3]>0) return p; el=el.parentElement||el.getRootNode().host;} return [255,255,255];};
const cr=(el)=>{const f=parse(getComputedStyle(el).color), b=bgOf(el); const L1=lum(f),L2=lum(b); return {fg:getComputedStyle(el).color,bg:b.join(','),ratio:+(((Math.max(L1,L2)+.05)/(Math.min(L1,L2)+.05)).toFixed(2)),fs:getComputedStyle(el).fontSize,fw:getComputedStyle(el).fontWeight};};
const o={};
o.status=[...document.querySelectorAll('pnip-status-solicitacao-utils .text-center')].map(e=>({t:e.textContent.trim(),cls:e.parentElement.className,...cr(e)}));
o.filters=[...document.querySelectorAll('pnip-multiple-search-table-utils span.br-tag span.text-gray-50')].slice(0,1).map(e=>({t:e.textContent,...cr(e)}));
o.meus=cr(document.querySelector('.br-tag .text-truncate'));
o.update=cr(document.querySelector('.mb-2'));
o.th=cr(document.querySelector('th'));
o.thbgs=[...document.querySelectorAll('thead th')].map(t=>getComputedStyle(t).backgroundColor);
o.td=cr(document.querySelector('tbody td'));
o.link=cr(document.querySelector('tbody a'));
o.anchors=[...document.querySelectorAll('tbody a')].slice(0,1).map(a=>({ti:a.tabIndex,attr:a.getAttribute('tabindex'),href:a.getAttribute('href')}));
o.tags=[...document.querySelectorAll('span.br-tag')].map(s=>({t:s.textContent.trim(),ti:s.tabIndex,role:s.getAttribute('role')}));
o.voltar=document.querySelector('button.br-button.secondary').getBoundingClientRect().toJSON();
o.pageSel=document.querySelector('#page').closest('.br-select').getBoundingClientRect().toJSON();
o.pageInp=document.querySelector('#page').getBoundingClientRect().toJSON();
o.lists=[...document.querySelectorAll('govbr-custom-pagination .br-list')].map(l=>({disp:getComputedStyle(l).display,vis:getComputedStyle(l).visibility,r:l.getBoundingClientRect().toJSON()}));
o.solic=[...document.querySelectorAll('tbody td:nth-child(5)')].map(td=>({sw:td.scrollWidth,cw:td.clientWidth,title:td.getAttribute('title')}));
o.iframe=document.querySelector('iframe').getBoundingClientRect().toJSON();
o.docH=document.documentElement.scrollHeight;
o.icons=[...document.querySelectorAll('pnip-mpa-processos i:not([aria-hidden]), pnip-header i:not([aria-hidden])')].map(i=>i.className+' | '+(i.parentElement.className));
o.imgs=[...document.querySelectorAll('img')].map(i=>({src:i.getAttribute('src'),alt:i.getAttribute('alt')}));
return o;}"}

{"function":"() => {
const o={};
const a=document.querySelector('tbody a'); a.focus(); o.aFocus=document.activeElement===a;
const s=document.querySelector('span.br-tag'); s.focus(); o.tagFocus=document.activeElement===s;
const pi=document.querySelector('#page'); const r=pi.getBoundingClientRect(); pi.scrollIntoView({block:'center'}); const r2=pi.getBoundingClientRect();
const top=document.elementFromPoint(r2.x+r2.width/2, r2.y+r2.height/2); o.atPageCenter=top.tagName+'.'+top.className+' '+top.textContent.trim().slice(0,20);
const pts=[[r2.x+5,r2.y+5],[r2.right-5,r2.bottom-5],[r2.x+20,r2.y+r2.height/2]].map(([x,y])=>{const e=document.elementFromPoint(x,y);return e.tagName+'.'+e.className;}); o.pts=pts;
// action br-button shadow
const bb=document.querySelectorAll('tbody br-button'); o.bb=[...bb].slice(0,4).map(b=>b.shadowRoot.innerHTML.replace(/<style>[\s\S]*?<\/style>/g,'').replace(/<!--.*?-->/g,'').replace(/\s+/g,' ').slice(0,400)+' || host:'+b.outerHTML.replace(/<!--.*?-->/g,'').replace(/\s(_ngcontent|_nghost)[^=\s]*(="[^"]*")?/g,'').slice(0,200));
const si=document.querySelector('br-input#search'); o.search=si.shadowRoot.innerHTML.replace(/<style>[\s\S]*?<\/style>/g,'').replace(/<!--.*?-->/g,'').replace(/\s+/g,' ').slice(0,800);
o.exp=document.querySelector('br-button[label=Exportar]').shadowRoot.innerHTML.replace(/<style>[\s\S]*?<\/style>/g,'').replace(/<!--.*?-->/g,'').replace(/\s+/g,' ').slice(0,300);
const sb=document.querySelector('button[aria-label=Buscar]').getBoundingClientRect(); const inp=si.getBoundingClientRect(); o.searchGeom={btn:sb.toJSON(),inp:inp.toJSON()};
return o;}"}

